import puppeteer from 'puppeteer';
import { readFileSync, writeFileSync } from 'fs';

const mermaidCode = readFileSync('/app/ecommerce-arch.mmd', 'utf8');

const browser = await puppeteer.launch({
  headless: true,
  args: ['--no-sandbox', '--disable-setuid-sandbox']
});

const page = await browser.newPage();
await page.setContent(`
<!DOCTYPE html>
<html>
<head>
  <script src="https://cdn.jsdelivr.net/npm/mermaid@11/dist/mermaid.min.js"></script>
</head>
<body>
  <pre class="mermaid">
${mermaidCode}
  </pre>
  <script>
    mermaid.initialize({
      startOnLoad: true,
      theme: 'neutral',
      securityLevel: 'loose'
    });
  </script>
</body>
</html>
`);

await page.waitForSelector('svg', { timeout: 30000 });

const svg = await page.$eval('svg', el => el.outerHTML);
writeFileSync('/app/output/result.svg', svg);

// Create PNG from SVG using canvas
const img = await page.evaluate(() => {
  const svgEl = document.querySelector('svg');
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');
  const img = new Image();
  canvas.width = svgEl.width.baseVal.value || 1200;
  canvas.height = svgEl.height.baseVal.value || 800;
  img.onload = () => {
    ctx.fillStyle = 'white';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(img, 0, 0);
  };
  img.src = 'data:image/svg+xml;base64,' + btoa(unescape(encodeURIComponent(svg)));
  return img;
});

await new Promise(r => img.onload = r);
const canvas = await page.evaluate(() => {
  const svgEl = document.querySelector('svg');
  const canvas = document.createElement('canvas');
  canvas.width = svgEl.width.baseVal.value || 1200;
  canvas.height = svgEl.height.baseVal.value || 800;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = 'white';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  const img = new Image();
  img.src = 'data:image/svg+xml;base64,' + btoa(unescape(encodeURIComponent(svgEl.outerHTML)));
  return new Promise(resolve => {
    img.onload = () => {
      ctx.drawImage(img, 0, 0);
      resolve(canvas.toDataURL('image/png').split(',')[1]);
    };
  });
});

writeFileSync('/app/output/result.png', Buffer.from(canvas, 'base64'));

await browser.close();
console.log('Diagram rendered to /app/output/result.png');

