import puppeteer from 'puppeteer';
import { readFileSync, writeFileSync } from 'fs';

const mermaidCode = readFileSync('/app/ecommerce-arch.mmd', 'utf8');

const browser = await puppeteer.launch({
  headless: true,
  args: ['--no-sandbox', '--disable-setuid-sandbox']
});

const page = await browser.newPage();
await page.setContent(`
<!DOCTYPE html>
<html>
<head>
  <script src="https://cdn.jsdelivr.net/npm/mermaid@11/dist/mermaid.min.js"></script>
  <style>
    body { margin: 0; padding: 20px; background: white; }
    .mermaid { display: flex; justify-content: center; }
  </style>
</head>
<body>
  <pre class="mermaid">
${mermaidCode}
  </pre>
  <script>
    mermaid.initialize({
      startOnLoad: true,
      theme: 'neutral',
      securityLevel: 'loose'
    });
  </script>
</body>
</html>
`);

await page.waitForSelector('svg', { timeout: 30000 });

const result = await page.evaluate(async () => {
  const svgEl = document.querySelector('svg');
  const serializer = new XMLSerializer();
  const svgString = serializer.serializeToString(svgEl);

  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');
  const img = new Image();

  const svgBlob = new Blob([svgString], { type: 'image/svg+xml;charset=utf-8' });
  const url = URL.createObjectURL(svgBlob);

  await new Promise((resolve, reject) => {
    img.onload = resolve;
    img.onerror = reject;
    img.src = url;
  });

  canvas.width = svgEl.width.baseVal.value || 1920;
  canvas.height = svgEl.height.baseVal.value || 1080;
  ctx.fillStyle = 'white';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.drawImage(img, 0, 0);

  return canvas.toDataURL('image/png').split(',')[1];
});

writeFileSync('/app/output/result.png', Buffer.from(result, 'base64'));
console.log('Diagram rendered to /app/output/result.png');

await browser.close();

